import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { toHex } from 'viem';
import { describe, expect, it } from 'vitest';

import { MockVrfProvider } from './mock-vrf.provider';
import {
  DEFAULT_PRIZE_SPLIT_BPS,
  SelectionError,
  WINNERS_DOMAIN,
  deriveWinnerIndices,
  selectWinners,
  splitPool,
} from './selection';

/** Vectors generated by packages/contracts (proven against DrawMath.sol by the forge suite). */
const VECTOR_1001 = {
  roundId: 1001n,
  randomWord: 62177841243127257463773158972188438612825451061698272662821620683145720262442n,
  totalEntries: 13n,
  winners: [9n, 5n, 4n, 12n, 2n, 0n, 7n, 1n, 10n, 6n, 8n, 11n, 3n],
};
const ROUND_1248 = {
  randomWord: 45127742960368135355701334915213245208257669240583708136230835151503622913791n,
  winners: [16582, 17038, 2954, 4692, 15817, 10733, 12952, 17844, 2699, 13163, 11026, 9979, 15568],
};

const entries = (n: number) =>
  Array.from({ length: n }, (_, i) => ({
    seq: i + 1,
    entryId: `e${i + 1}`,
    userId: `u${(i % 7) + 1}`,
  }));

describe('winner selection (mirror of DrawMath.deriveWinners / splitPool)', () => {
  it('uses the contract domain tag', () => {
    expect(WINNERS_DOMAIN).toMatch(/^0x[0-9a-f]{64}$/);
  });

  it('matches the contract vector for 13 entries', () => {
    expect(
      deriveWinnerIndices(
        VECTOR_1001.roundId,
        VECTOR_1001.randomWord,
        VECTOR_1001.totalEntries,
        13n,
      ),
    ).toEqual(VECTOR_1001.winners);
  });

  it('matches the round #1,248 fixture draw (18,640 entries) and its prize amounts', () => {
    const indices = deriveWinnerIndices(1248n, ROUND_1248.randomWord, 18_640n, 13n);
    expect(indices.map(Number)).toEqual(ROUND_1248.winners);
    const amounts = splitPool(186_400_000_000n, DEFAULT_PRIZE_SPLIT_BPS);
    expect(amounts[0]).toBe(93_200_000_000n);
    expect(amounts.reduce((a, b) => a + b, 0n)).toBe(186_400_000_000n);
  });

  it('agrees with every winner vector in packages/contracts/test/fixtures (when present)', () => {
    const file = resolve(
      __dirname,
      '../../../../../packages/contracts/test/fixtures/round-1248.json',
    );
    if (!existsSync(file)) return;
    const fixture = JSON.parse(readFileSync(file, 'utf8')) as {
      winnerVectors: {
        roundId: string;
        randomWord: string;
        totalEntries: string;
        count: string;
        winners: string[];
      }[];
      draw: { randomWord: string; winners: number[] };
      settlement: { prizeAmounts: string[] };
    };
    for (const v of fixture.winnerVectors) {
      expect(
        deriveWinnerIndices(
          BigInt(v.roundId),
          BigInt(v.randomWord),
          BigInt(v.totalEntries),
          BigInt(v.count),
        ),
      ).toEqual(v.winners.map(BigInt));
    }
    expect(splitPool(186_400_000_000n, DEFAULT_PRIZE_SPLIT_BPS).map(String)).toEqual(
      fixture.settlement.prizeAmounts,
    );
  });

  it('is deterministic and returns distinct entries ranked 1..13 whose prizes sum to the pool', () => {
    const word = MockVrfProvider.wordFor('mock-1-test');
    const a = selectWinners({
      roundId: 1n,
      randomWord: word,
      entries: entries(500),
      pool: '5000.00',
    });
    const b = selectWinners({
      roundId: 1n,
      randomWord: word,
      entries: entries(500),
      pool: '5000.00',
    });
    expect(a).toEqual(b);
    expect(a).toHaveLength(13);
    expect(new Set(a.map((w) => w.entrySeq)).size).toBe(13);
    expect(a.map((w) => w.rank)).toEqual(Array.from({ length: 13 }, (_, i) => i + 1));
    expect(a.map((w) => w.tier).slice(0, 4)).toEqual(['first', 'second', 'third', 'runner_up']);
    const total = a.reduce((acc, w) => acc + BigInt(Math.round(Number(w.amount) * 1e6)), 0n);
    expect(total).toBe(5_000_000_000n);
    expect(a[1]!.amount).toBe('1000.00');
  });

  it('changes with the random word and the round id', () => {
    const e = entries(1000);
    const base = selectWinners({
      roundId: 7n,
      randomWord: toHex(123n, { size: 32 }),
      entries: e,
      pool: '10000.00',
    });
    const otherWord = selectWinners({
      roundId: 7n,
      randomWord: toHex(124n, { size: 32 }),
      entries: e,
      pool: '10000.00',
    });
    const otherRound = selectWinners({
      roundId: 8n,
      randomWord: toHex(123n, { size: 32 }),
      entries: e,
      pool: '10000.00',
    });
    expect(otherWord.map((w) => w.entrySeq)).not.toEqual(base.map((w) => w.entrySeq));
    expect(otherRound.map((w) => w.entrySeq)).not.toEqual(base.map((w) => w.entrySeq));
  });

  it('with fewer entries than prizes, every entry wins once and the 1st prize absorbs undrawn shares', () => {
    const w = selectWinners({
      roundId: 3n,
      randomWord: toHex(42n, { size: 32 }),
      entries: entries(3),
      pool: '30.00',
    });
    expect(w).toHaveLength(3);
    expect(new Set(w.map((x) => x.entrySeq))).toEqual(new Set([1, 2, 3]));
    expect(w.map((x) => x.amount)).toEqual(['21.00', '6.00', '3.00']);
  });

  it('refuses a non-canonical entry list and invalid splits', () => {
    const bad = [{ seq: 2, entryId: 'x', userId: 'u' }];
    expect(() =>
      selectWinners({
        roundId: 1n,
        randomWord: toHex(1n, { size: 32 }),
        entries: bad,
        pool: '10.00',
      }),
    ).toThrow(SelectionError);
    expect(() =>
      selectWinners({
        roundId: 1n,
        randomWord: toHex(1n, { size: 32 }),
        entries: entries(5),
        pool: '50.00',
        prizeSplitBps: [5000, 4000],
      }),
    ).toThrow(/10000/);
    expect(() => deriveWinnerIndices(1n, 1n, 0n, 1n)).toThrow(SelectionError);
  });
});
